-- Datos FICTICIOS para probar las pantallas de la Ola 1 en la base local.
begin;
set local session_replication_role = replica;
-- Esquemas: todos menos FABIOLA (sin esquema de pago)
select '0a000000-0000-4000-8000-000000000001', p, '0f000000-0000-4000-8000-000000000001', '0e000000-0000-4000-8000-000000000030', s, 'bruto', 30, '2025-01-01', '0c000000-0000-4000-8000-000000000001'
from (values ('0a100000-0000-4000-8000-000000000011'::uuid, 20000), ('0a100000-0000-4000-8000-000000000012'::uuid, 15000),
             ('0a100000-0000-4000-8000-000000000013'::uuid, 12000), ('0a100000-0000-4000-8000-000000000014'::uuid, 18000),
             ('0a100000-0000-4000-8000-000000000015'::uuid, 11000), ('0a100000-0000-4000-8000-000000000021'::uuid, 14000),
             ('0a100000-0000-4000-8000-000000000022'::uuid, 13000)) v(p, s);
-- Historial de asignaciones desde el lunes 26-oct (datos de prueba)
select tenant_id, id, coordinador_id, '2026-10-26', 'carga_inicial', 'semilla local' from public.personal
where tenant_id = '0a000000-0000-4000-8000-000000000001' and coordinador_id is not null;
commit;
